// Pedidos de alteração → aviso em privado no Slack (só para quem está em pa_config.slack_destinos).
// Reserva antes de mandar: o webhook imediato e a rodada de 5 min nunca mandam a mesma mensagem.
const URL = 'https://mbvybujpkwuorhtdzcde.supabase.co/rest/v1/rpc/';
const H = { apikey: '<SUPABASE_ANON_KEY>', Authorization: 'Bearer <SUPABASE_ANON_KEY>', 'Content-Type': 'application/json' };
const SEG = '<SEGREDO_N8N>';
const rpc = (fn, body) => this.helpers.httpRequest({ method: 'POST', url: URL + fn, headers: H, body, json: true });
const SLACK = '<SLACK_BOT_TOKEN_REMOCAO>';
const out = [];
const p = await rpc('pa_slack_reservar', { p_segredo: SEG });
if (!p || !p.ok) throw new Error('pa_slack_reservar recusou (segredo?)');
for (const m of (p.mensagens || [])) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST', url: 'https://slack.com/api/chat.postMessage',
      headers: { Authorization: 'Bearer ' + SLACK, 'Content-Type': 'application/json; charset=utf-8' },
      body: { channel: m.slack_id, text: m.texto, unfurl_links: false, unfurl_media: false }, json: true,
    });
    if (!r.ok) throw new Error('Slack: ' + r.error);
    await rpc('pa_slack_confirmar', { p_segredo: SEG, p_pedido: m.pedido, p_slack_id: m.slack_id, p_ts: r.ts });
    out.push({ pedido: m.pedido, ok: true });
  } catch (e) {
    out.push({ pedido: m.pedido, ok: false, erro: String(e.message || e).slice(0, 160) });
  }
}
return [{ json: { enviados: out.filter(o => o.ok).length, detalhe: out } }];
